# Fixed implementation for testing
class BaseNB_Fixed(ClassifierMixin, BaseEstimator, metaclass=ABCMeta):
    @abstractmethod
    def fit(self, X, y):
        pass

    @abstractmethod
    def predict(self, X):
        pass

def test_mixin_method_resolution_order():
    """Test that ClassifierMixin methods take precedence over BaseEstimator."""
    # Create a concrete implementation using the buggy base class
    class TestNB_Buggy(BaseNB_Buggy):
        def fit(self, X, y):
            return self

        def predict(self, X):
            return [0] * len(X)

    # Create a concrete implementation using the fixed base class
    class TestNB_Fixed(BaseNB_Fixed):
        def fit(self, X, y):
            return self

        def predict(self, X):
            return [0] * len(X)

    # Test that the fixed version properly resolves method order
    nb_fixed = TestNB_Fixed()
    assert isinstance(nb_fixed, ClassifierMixin)
    assert isinstance(nb_fixed, BaseEstimator)

    # The key test: ensure ClassifierMixin's methods take precedence
    # This would fail in the buggy version if there were conflicting methods
    # (though in this specific case we're testing the MRO is correct for future method additions)

    # More concrete test: check that ClassifierMixin's score method is available
    # and properly overrides any potential score method from BaseEstimator
    X = [[0], [1]]
    y = [0, 1]
    nb_fixed.fit(X, y)
    score = nb_fixed.score(X, y)  # score comes from ClassifierMixin
    assert 0 <= score <= 1  # basic sanity check

    # The buggy version would have different method resolution order
    # which could cause problems if BaseEstimator and ClassifierMixin had conflicting methods
    nb_buggy = TestNB_Buggy()
    nb_buggy.fit(X, y)

