        self.n_jobs = n_jobs

    def _get_effective_n_jobs(self):
        n_cpus = cpu_count()
        if self.n_jobs is None:
            return 1
        elif self.n_jobs == -1:
            return n_cpus
        elif self.n_jobs < -1:
            # Original buggy implementation: n_cpus + 1 - n_jobs
            # Fixed implementation: n_cpus + 1 + n_jobs
            return n_cpus + 1 + self.n_jobs
